    {{-- Menu contestuale cartelle (tasto destro), condiviso da albero e tile.
         Le righe/tile cartella fanno $dispatch('asset-folder-menu', {id, x, y});
         le voci montano le azioni già definite sulla pagina via $wire.mountAction.
         position:fixed → si posiziona al cursore indipendentemente dallo scroll.
         showAt() clampa x/y dopo il render così il menu non esce mai dalla viewport
         quando il click avviene vicino al bordo destro/inferiore. --}}
    <div
        x-data="{
            open: false, x: 0, y: 0, folderId: null,
            showAt(cx, cy) {
                this.x = cx; this.y = cy; this.open = true;
                this.$nextTick(() => {
                    const r = this.$refs.panel.getBoundingClientRect();
                    this.x = Math.max(8, Math.min(cx, window.innerWidth - r.width - 8));
                    this.y = Math.max(8, Math.min(cy, window.innerHeight - r.height - 8));
                });
            },
        }"
        x-on:asset-folder-menu.window="folderId = $event.detail.id; showAt($event.detail.x, $event.detail.y)"
        x-on:asset-media-menu.window="open = false"
        x-on:click.away="open = false"
        x-on:keydown.escape.window="open = false"
        x-on:scroll.window="open = false"
    >
        <div
            x-show="open"
            x-cloak
            x-transition.opacity.duration.100ms
            x-ref="panel"
            x-bind:style="`top: ${y}px; left: ${x}px;`"
            class="fixed z-50 min-w-44 py-1 rounded-lg bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 shadow-lg"
        >
            {{-- Scarica/condividi cartella = tutti i file del suo sottoalbero
                 (niente "Duplica" sulle cartelle, per scelta). --}}
            <button type="button" x-on:click="open = false; $wire.mountAction('downloadFolder', { folder: folderId })" class="w-full text-left flex items-center gap-2 px-3 py-1.5 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-800">
                <x-filament::icon :icon="\Filament\Support\Icons\Heroicon::OutlinedArrowDownTray" class="h-4 w-4 shrink-0 text-gray-400" />
                {{ __('digital-hub::assets.download') }}
            </button>
            <button type="button" x-on:click="open = false; $wire.mountAction('shareFolder', { folder: folderId })" class="w-full text-left flex items-center gap-2 px-3 py-1.5 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-800">
                <x-filament::icon :icon="\Filament\Support\Icons\Heroicon::OutlinedShare" class="h-4 w-4 shrink-0 text-gray-400" />
                {{ __('digital-hub::assets.share') }}
            </button>
            <button type="button" x-on:click="open = false; $wire.mountAction('moveFolder', { folder: folderId })" class="w-full text-left flex items-center gap-2 px-3 py-1.5 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-800">
