            <button type="button" x-on:click="open = false; $wire.mountAction('renameFolder', { folder: folderId })" class="w-full text-left flex items-center gap-2 px-3 py-1.5 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-800">
