            <button type="button" x-on:click="open = false; $wire.mountAction('deleteFolder', { folder: folderId })" class="w-full text-left flex items-center gap-2 px-3 py-1.5 text-sm text-danger-600 dark:text-danger-400 hover:bg-gray-100 dark:hover:bg-gray-800">
