public function infoAssetAction(): Action
{
    return Action::make('infoAsset')
        ->label(__('digital-hub::assets.info'))
        ->icon(Heroicon::OutlinedInformationCircle)
        ->slideOver()
        ->modalHeading(__('digital-hub::assets.info_heading'))
        ->modalSubmitAction(false)
        ->modalCancelActionLabel(__('digital-hub::assets.close'))
        // "Chiudi" spinto a destra (ms-auto) nel footer, che di default
        // allinea tutto a sinistra (vedi modalFooterActionsAlignment sotto):
        // le azioni sul file restano a sinistra, "Chiudi" isolato a destra.
        ->modalCancelAction(fn (Action $action): Action => $action->extraAttributes(['class' => 'ms-auto']))
        // azioni sul file (14e) nel footer dello slideover: riusano le
        // stesse action del menu contestuale, con `media` già in argument.
        ->extraModalFooterActions(function (array $arguments): array {
            $media = $this->findOwnedMedia($arguments['media'] ?? null);
            if ($media === null) {
                return [];
            }

            return [
                $this->downloadAssetAction()->button()->color('grayFull')->extraAttributes(['class' => '!text-black [&>.fi-icon]:!text-black'])->arguments(['media' => $media->getKey()]),
                $this->shareAssetAction()->button()->color('grayFull')->extraAttributes(['class' => '!text-black [&>.fi-icon]:!text-black'])->arguments(['media' => $media->getKey()]),
                $this->duplicateAssetAction()->button()->color('grayFull')->extraAttributes(['class' => '!text-black [&>.fi-icon]:!text-black'])->arguments(['media' => $media->getKey()]),
                $this->deleteAssetAction()->button()->arguments(['media' => $media->getKey()]),
            ];
        })
        ->modalFooterActionsAlignment(Alignment::Start)
        ->schema(function (Schema $schema, array $arguments): Schema {
            $media = $this->findOwnedMedia($arguments['media'] ?? null);

            return $schema->components($media === null ? [] : [
                // anteprima sempre visibile, sopra ai tab
                ViewEntry::make('preview')
                    ->hiddenLabel()
                    ->view('digital-hub::filament.partials.asset-preview', [
                        'media' => $media,
                        // URL protetti da sessione: nel pannello l'utente è autenticato
                        'posterUrl' => AssetPreview::url($media),
                        'originalUrl' => AssetUrl::original($media),
                    ]),
                $this->assetInfoTabs($media),
            ]);
        });
}

/**
 * Tab del pannello info: "Informazioni" (metadati curati/normalizzati) e
 * "Metadati completi" (`extracted_metadata` grezzo, un blocco per tipo). Il
 * secondo tab compare solo se ci sono metadati estratti.
 */
private function assetInfoTabs(Media $media): Tabs
{
    // prima tab con informazioni"
    $tabs = [
        Tab::make(__('digital-hub::assets.info_tab_summary'))
            ->schema($this->assetInfoEntries($media)),
    ];

    // seconda tab con le sezioni degli altri gruppi di metadati
    $sections = $this->assetMetadataSections($media);
    if ($sections !== []) {
        $tabs[] = Tab::make(__('digital-hub::assets.info_tab_full'))
            ->schema($sections);
    }

    return Tabs::make()->tabs($tabs);
}

/**
 * Sezioni collassabili con i metadati estratti grezzi (`extracted_metadata`),
 * un blocco per chiave presente (`common`/`exif`/`iptc`/`xmp`). I valori
 * annidati (sezioni EXIF, liste IPTC) sono appiattiti in dot-notation perché
 * il KeyValueEntry rende solo coppie chiave→scalare. Vuoto se non ci sono
 * metadati (media non ancora processato).
 *
 * @return list<Section>
 */
private function assetMetadataSections(Media $media): array
{
    $metadata = ExtractedMetadata::forMedia($media);

    $labels = [
        'common' => __('digital-hub::assets.meta_block_common'),
        'exif' => 'EXIF',
        'iptc' => 'IPTC',
        'xmp' => 'XMP',
    ];

    $sections = [];
    foreach ($labels as $key => $label) {
        $block = $metadata[$key] ?? null;
        if (! is_array($block)) {
            continue;
        }

        $flat = ExtractedMetadata::flatten($block);
        if ($flat === []) {
            continue;
        }

        $sections[] = Section::make($label)
            ->heading('')
            // ->collapsible()
            // ->collapsed($key !== 'common') // i generali aperti, i blocchi grezzi chiusi
            ->schema([
                Fieldset::make($label)
                    ->columnSpanFull()
                    ->columns(1)
                    ->contained(false)
                    ->schema([
                        KeyValueEntry::make("meta_{$key}")
                            ->hiddenLabel()
                            ->state($flat)
                            ->keyLabel(__('digital-hub::assets.meta_key'))
                            ->valueLabel(__('digital-hub::assets.meta_value')),
                    ]),
            ]);
    }

    if ($primaryPalette !== null) {
        $panel->colors([
            'primary' => $primaryPalette,
        ]);
    }

    // Filament tratta il colore 'gray' come stile "neutro/outline" e non
    // applica uno sfondo pieno ai bottoni. Registriamo 'grayFull' per avere
    // bottoni con sfondo grigio pieno (#EFEFEF) dove serve, senza toccare
    // lo stile di 'gray' altrove nel panel. Quasi tutte le shade sono
    // impostate sullo stesso colore così lo sfondo resta #EFEFEF
    // indipendentemente dalla shade usata dal componente bottone; la shade
    // 500 (usata per l'hover) è leggermente più scura per dare un minimo
    // di contrasto al passaggio del mouse.
    $panel->colors([
        'grayFull' => [
            ...array_fill_keys([50, 100, 200, 300, 400, 600, 700, 800, 900, 950], '#EFEFEF'),
            500 => '#E0E0E0',
        ],
    ]);



}

/**
 * Risolve la palette colori (shade 50..950) da usare come primary del panel.
 * Ordine: setting general.primary_color (modalità "palette" = nome costante
 * Filament, "custom" = hex libero da cui generare la palette), poi fallback
 * sul config. Se la lettura delle settings fallisce (DB/tabella non

