3	namespace Filament\Support\View\Components\ColorMaps;
4	
5	use Filament\Support\Colors\Color;
6	use LogicException;
7	
8	class ButtonComponentColorMap
9	{
10	    /**
11	     * @var array<int, string>
12	     */
13	    protected array $palette;
14	
15	    protected float $minContrastRatio = Color::WCAG_AA_TEXT;
16	
17	    /**
18	     * @var list<array{bg: int, hover: int, alternateHover: int|null}>
19	     */
20	    protected array $lightBackgrounds = [];
21	
22	    /**
23	     * @var list<array{bg: int, hover: int, alternateHover: int|null}>
24	     */
25	    protected array $darkBackgrounds = [];
26	
27	    /**
28	     * @param  array<int, string>  $palette
29	     */
30	    final public function __construct(array $palette)
31	    {
32	        ksort($palette);
33	
34	        $this->palette = $palette;
35	    }
36	
37	    /**
38	     * @param  array<int, string>  $palette
39	     */
40	    public static function make(array $palette): static
41	    {
42	        return new static($palette);
43	    }
44	
45	    public function minContrastRatio(float $ratio): static
46	    {
47	        $this->minContrastRatio = $ratio;
48	
49	        return $this;
50	    }
51	
52	    /**
53	     * Add a candidate `(bg, hover, alternateHover?)` triplet for light mode. Each call appends
54	     * a candidate; the resolver evaluates them in the order added.
55	     *
56	     * `$alternateHover` is consulted whenever the main `$hover` isn't a good match — either
57	     * because it doesn't produce light text alongside a vibrant `$bg`, or because its
58	     * lightness disagrees with `$bg`'s in the fallback case.
59	     *
60	     * The last candidate added serves as the guaranteed fallback for palettes where no
61	     * candidate produces light text on its `$bg` — pale colors like yellow.
62	     */
63	    public function lightBackground(int $bg, int $hover, ?int $alternateHover = null): static
64	    {
65	        $this->lightBackgrounds[] = ['bg' => $bg, 'hover' => $hover, 'alternateHover' => $alternateHover];
66	
67	        return $this;
68	    }
69	
70	    /**
71	     * Add a candidate `(bg, hover, alternateHover?)` triplet for dark mode. Each call appends
72	     * a candidate; the resolver evaluates them in the order added using the same two-pass
73	     * algorithm as `lightBackground()`.
74	     */
75	    public function darkBackground(int $bg, int $hover, ?int $alternateHover = null): static
76	    {
77	        $this->darkBackgrounds[] = ['bg' => $bg, 'hover' => $hover, 'alternateHover' => $alternateHover];
78	
79	        return $this;
80	    }
81	
82	    /**
83	     * @return array<string, int>
84	     */
85	    public function get(): array
86	    {
87	        if (empty($this->lightBackgrounds)) {
88	            throw new LogicException('At least one `lightBackground()` candidate must be configured before calling `get()`.');
89	        }
90	
91	        if (empty($this->darkBackgrounds)) {
92	            throw new LogicException('At least one `darkBackground()` candidate must be configured before calling `get()`.');
93	        }
94	
95	        $textForBg = $this->resolveTextForEachBackground();
96	
97	        $textLightness = $this->probeTextLightness($textForBg);
98	
99	        [$bg, $hoverBg] = $this->pickBackgroundShades($textLightness, $this->lightBackgrounds);
100	        [$darkBg, $darkHoverBg] = $this->pickBackgroundShades($textLightness, $this->darkBackgrounds);
101	
102	        return [
103	            'bg' => $bg,
104	            'hover:bg' => $hoverBg,
105	            'dark:bg' => $darkBg,
106	            'dark:hover:bg' => $darkHoverBg,
107	            'text' => $textForBg[$bg] ?? 0,
108	            'hover:text' => $textForBg[$hoverBg] ?? 0,
109	            'dark:text' => $textForBg[$darkBg] ?? 0,
110	            'dark:hover:text' => $textForBg[$darkHoverBg] ?? 0,
111	        ];
112	    }
113	
114	    /**
115	     * For each background shade in the palette, find the best text shade. Walks dark→light
116	     * looking for a dark text first (>= 800), then tries shade 50 as a light fallback. Returns
117	     * 0 (white) when nothing else qualifies.
118	     *
119	     * @return array<int, int>
120	     */
121	    protected function resolveTextForEachBackground(): array
122	    {
123	        $textForBg = [];
124	
125	        $possibleDarkTextShades = $this->palette;
126	        unset($possibleDarkTextShades[array_key_first($possibleDarkTextShades)]);
127	
128	        $isFallbackAccessibleOnDarkerShades = true;
129	
130	        foreach (array_keys($this->palette) as $bgShade) {
131	            foreach ($possibleDarkTextShades as $darkTextShade => $darkTextValue) {
132	                if (
133	                    ($darkTextShade >= 800) &&
134	                    (Color::calculateContrastRatio($this->palette[$bgShade], $darkTextValue) >= $this->minContrastRatio)
135	                ) {
136	                    $textForBg[$bgShade] = $darkTextShade;
137	
138	                    continue 2;
139	                }
140	
141	                unset($possibleDarkTextShades[$darkTextShade]);
142	            }
143	
144	            if (
145	                $isFallbackAccessibleOnDarkerShades &&
146	                array_key_exists(50, $this->palette)
147	            ) {
148	                if (Color::calculateContrastRatio($this->palette[$bgShade], $this->palette[50]) >= $this->minContrastRatio) {
149	                    $textForBg[$bgShade] = 50;
150	
151	                    continue;
152	                }
153	
154	                $isFallbackAccessibleOnDarkerShades = false;
155	            }
156	
157	            $textForBg[$bgShade] = 0;
158	        }
159	
160	        return $textForBg;
161	    }
162	
163	    /**
164	     * @param  array<int, int>  $textForBg
165	     * @return array<int, bool>
166	     */
167	    protected function probeTextLightness(array $textForBg): array
168	    {
169	        $shades = [];
170	
171	        foreach ([...$this->lightBackgrounds, ...$this->darkBackgrounds] as $candidate) {
172	            $shades[] = $candidate['bg'];
173	            $shades[] = $candidate['hover'];
174	
175	            if ($candidate['alternateHover'] !== null) {
176	                $shades[] = $candidate['alternateHover'];
177	            }
178	        }
179	
180	        $lightness = [];
181	
182	        foreach (array_unique($shades) as $shade) {
183	            $textShade = $textForBg[$shade] ?? 0;
184	
185	            $lightness[$shade] = ($textShade === 0) || Color::isLight($this->palette[$textShade] ?? 'oklch(1 0 0)');
186	        }
187	
188	        return $lightness;
189	    }
190	
191	    /**
192	     * Two-pass selection over an ordered list of background candidates. Pass 1 prefers
193	     * candidates whose `bg` produces light text and tries `hover` then `alternateHover`.
194	     * Pass 2 takes the last candidate as guaranteed fallback with smart-hover selection
195	     * (consistency-based pick between `hover` and `alternateHover`).
196	     *
197	     * @param  array<int, bool>  $textLightness
198	     * @param  list<array{bg: int, hover: int, alternateHover: int|null}>  $candidates
199	     * @return array{int, int}
200	     */
201	    protected function pickBackgroundShades(array $textLightness, array $candidates): array
202	    {
203	        foreach ($candidates as $candidate) {
204	            if (! ($textLightness[$candidate['bg']] ?? false)) {
205	                continue;
206	            }
207	
208	            if ($textLightness[$candidate['hover']] ?? false) {
209	                return [$candidate['bg'], $candidate['hover']];
210	            }
211	
212	            if (($candidate['alternateHover'] !== null) && ($textLightness[$candidate['alternateHover']] ?? false)) {
213	                return [$candidate['bg'], $candidate['alternateHover']];
214	            }
215	        }
216	
217	        $fallback = end($candidates);
218	
219	        $hover = (($textLightness[$fallback['bg']] ?? false) === ($textLightness[$fallback['hover']] ?? false))
220	            ? $fallback['hover']
221	            : ($fallback['alternateHover'] ?? $fallback['hover']);
222	
223	        return [$fallback['bg'], $hover];
224	    }
225	}
