9	use Filament\Support\View\Components\Contracts\HasColor;
10	use Filament\Support\View\Components\Contracts\HasDefaultGrayColor;
11	
12	class ButtonComponent implements HasColor, HasDefaultGrayColor
13	{
14	    public function __construct(
15	        public readonly bool $isOutlined = false,
16	    ) {}
17	
18	    /**
19	     * @param  array<int, string>  $color
20	     * @return array<string, int>
21	     */
22	    public function getColorMap(array $color): array
23	    {
24	        $gray = FilamentColor::getColor('gray');
25	
26	        if ($this->isOutlined) {
27	            return ComponentColorMap::make($color)
28	                ->slot('text', surface: $gray[50], minRatio: Color::WCAG_AA_TEXT, fallback: 900)
29	                ->slot('dark:text', surface: $gray[700], minRatio: Color::WCAG_AA_TEXT, maxShade: 500, shouldStartFromDarkest: true, fallback: 200)
30	                ->get();
31	        }
32	
33	        return ButtonComponentColorMap::make($color)
34	            ->minContrastRatio(Color::WCAG_AA_TEXT)
35	            ->lightBackground(bg: 600, hover: 500)
36	            ->lightBackground(bg: 400, hover: 300, alternateHover: 500)
37	            ->darkBackground(bg: 600, hover: 500, alternateHover: 700)
38	            ->get();
39	    }
40	}
