// 'grayFull' ha tutte le shade sullo stesso grigio chiaro (#EFEFEF): Filament
// sceglie la stessa shade sia per il light che per il dark background, quindi
// lo sfondo del bottone resta identico nei due temi. Sovrascriviamo qui lo
// sfondo/testo per la dark mode (sintassi Tailwind 4: "!" importante in coda).
$grayFullButtonClasses = 'text-black! [&>.fi-icon]:text-black! '
    . 'dark:bg-gray-700! dark:hover:bg-gray-600! dark:text-white! dark:[&>.fi-icon]:text-white!';

return [
    $this->downloadAssetAction()->button()->color('grayFull')->extraAttributes(['class' => $grayFullButtonClasses])->arguments(['media' => $media->getKey()]),
    $this->shareAssetAction()->button()->color('grayFull')->extraAttributes(['class' => $grayFullButtonClasses])->arguments(['media' => $media->getKey()]),
    $this->duplicateAssetAction()->button()->color('grayFull')->extraAttributes(['class' => $grayFullButtonClasses])->arguments(['media' => $media->getKey()]),
    $this->deleteAssetAction()->button()->arguments(['media' => $media->getKey()]),
];

